<?php require 'db.php';if(role()!=='admin'){http_response_code(403);die('Accès refusé');}
[$w,$p]=mvq($_GET);$kl=['entree'=>'Entrée','sortie'=>'Sortie','ajust'=>'Correction'];
$q=$pdo->prepare("SELECT moved_at,item_name,type,kind,qty,unit,note FROM stock_moves WHERE $w ORDER BY moved_at,id");$q->execute($p);
$A=[['Date','Élément','Type','Mouvement','Quantité','Unité','Note']];foreach($q as $r)$A[]=[$r['moved_at'],$r['item_name'],$r['type'],$kl[$r['kind']],(float)$r['qty'],$r['unit'],(string)$r['note']];
$q=$pdo->prepare("SELECT item_name,type,unit,SUM(IF(kind='entree',qty,0)) a,SUM(IF(kind='sortie',qty,0)) b FROM stock_moves WHERE $w GROUP BY item_name,type,unit ORDER BY item_name");$q->execute($p);
$B=[['Élément','Type','Unité','Total entrées','Total sorties']];foreach($q as $r)$B[]=[$r['item_name'],$r['type'],$r['unit'],(float)$r['a'],(float)$r['b']];
$fn='stock_dakere_'.date('Y-m-d_Hi');
function sheet($R){$x='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cols><col min="1" max="7" width="20" customWidth="1"/></cols><sheetData>';
 foreach($R as $i=>$r){$x.='<row r="'.($i+1).'">';foreach($r as $c){$x.=is_float($c)||is_int($c)?'<c><v>'.$c.'</v></c>':'<c t="inlineStr"><is><t xml:space="preserve">'.htmlspecialchars($c,ENT_XML1).'</t></is></c>';}$x.='</row>';}
 return $x.'</sheetData></worksheet>';}
if(class_exists('ZipArchive')){$f=tempnam(sys_get_temp_dir(),'x');$z=new ZipArchive;$z->open($f,ZipArchive::OVERWRITE);
 $z->addFromString('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');
 $z->addFromString('_rels/.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
 $z->addFromString('xl/workbook.xml','<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Mouvements" sheetId="1" r:id="rId1"/><sheet name="Synthèse" sheetId="2" r:id="rId2"/></sheets></workbook>');
 $z->addFromString('xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/></Relationships>');
 $z->addFromString('xl/worksheets/sheet1.xml',sheet($A));$z->addFromString('xl/worksheets/sheet2.xml',sheet($B));$z->close();
 header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$fn.'.xlsx"');header('Content-Length: '.filesize($f));readfile($f);unlink($f);exit;}
// Secours si ZipArchive est absent : CSV compatible Excel
header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$fn.'.csv"');echo "\xEF\xBB\xBF";$o=fopen('php://output','w');foreach($A as $r)fputcsv($o,$r,';');
